<script setup lang="ts">
import { computed, onBeforeUnmount } from 'vue';
import type {FlightControlKey,LandingFlightSnapshot} from '../../contracts';

const props=defineProps<{flight:Readonly<LandingFlightSnapshot>;paused:boolean;guidance:{desiredSpeed:number}}>();
const emit=defineEmits<{hold:[key:FlightControlKey,down:boolean];nudge:[key:FlightControlKey];throttle:[value:number];legs:[];assist:[];pause:[];retry:[];continue:[]}>();
const keys=[['KeyW','W','Nose down'],['KeyS','S','Nose up'],['KeyA','A','Steer left'],['KeyD','D','Steer right']] as const;
const hint=computed(()=>{const s=props.flight;if(s.status!=='flying')return s.result;if(s.phase==='space')return 'W nose down · S nose up';if(s.phase==='entry')return 'Atmospheric entry · keep a steady angle';const g=props.guidance;return s.verticalSpeed<g.desiredSpeed-2?'Increase thrust to brake':s.verticalSpeed>g.desiredSpeed+2?'Ease thrust to descend':Math.abs(s.offset)>12?'Line up with the pad':s.altitude<100&&!s.legs?'Space · deploy legs':'Hold a gentle descent';});
function down(event:PointerEvent,key:FlightControlKey){(event.currentTarget as Element).setPointerCapture(event.pointerId);emit('hold',key,true);}
onBeforeUnmount(()=>[...keys.map(([key])=>key),'KeyQ','KeyE'].forEach(key=>emit('hold',key as FlightControlKey,false)));
</script>
<template>
 <section class="landing-controls" aria-label="Live Mars landing controls">
  <div class="descent-title"><small>{{ flight.phase==='space'?'MARS / SPACE APPROACH':flight.phase==='entry'?'MARS / ATMOSPHERIC ENTRY':'ARES / BASE APPROACH' }}</small><strong role="status">{{ paused?'PAUSED':flight.status==='retry'?'TRY AGAIN':flight.status==='landed'?'TOUCHDOWN':hint }}</strong><progress class="heat" :value="flight.heat" max="1" aria-label="Entry heat indicator"/></div>
  <div class="telemetry" aria-label="Landing telemetry"><div><small>ALTITUDE</small><strong data-landing-altitude :data-metres="flight.altitude">{{ flight.altitude>=1000?(flight.altitude/1000).toFixed(1):flight.altitude.toFixed(0) }} <em>{{ flight.altitude>=1000?'km':'m' }}</em></strong></div><div :class="{danger:flight.verticalSpeed < -8}"><small>{{ flight.verticalSpeed>0?'RISING':'DESCENT' }}</small><strong data-landing-speed>{{ Math.abs(flight.verticalSpeed).toFixed(1) }} <em>m/s</em></strong></div><div><small>FORWARD</small><strong data-landing-forward>{{ flight.forwardSpeed>=1000?(flight.forwardSpeed/1000).toFixed(1):flight.forwardSpeed.toFixed(0) }} <em>{{ flight.forwardSpeed>=1000?'km/s':'m/s' }}</em></strong></div><div><small>FUEL</small><strong>{{ Math.round(flight.fuel/300*100) }} <em>%</em></strong></div></div>
  <div class="alignment"><span>PAD CENTER</span><div class="lane"><i class="pad"/><b :style="{left:(50+Math.max(-45,Math.min(45,flight.offset*.9)))+'%'}">▼</b></div><strong data-landing-offset>{{ Math.abs(flight.offset).toFixed(1) }} m {{ flight.offset<-.5?'LEFT':flight.offset>.5?'RIGHT':'CENTERED' }} · {{ flight.pitch.toFixed(0) }}° pitch · {{ flight.bank.toFixed(0) }}° bank</strong></div>
  <div class="pilot-pad">
   <template v-if="flight.status==='flying'">
    <label>THRUST · Q− / E+ <strong>{{ Math.round(flight.throttle*100) }}%</strong><input type="range" min="0" max="100" :value="flight.throttle*100" :disabled="paused" aria-label="Landing throttle" @input="emit('throttle',Number(($event.target as HTMLInputElement).value)/100)"/></label>
    <div class="thrust-keys"><button aria-label="Reduce thrust" :disabled="paused" @pointerdown="down($event,'KeyQ')" @pointerup="emit('hold','KeyQ',false)" @pointercancel="emit('hold','KeyQ',false)" @lostpointercapture="emit('hold','KeyQ',false)" @click="emit('nudge','KeyQ')">Q −</button><span>{{ flight.phase==='approach'?'ENGINES ACTIVE':'ENTRY · ENGINES STANDBY' }}</span><button aria-label="Increase thrust" :disabled="paused" @pointerdown="down($event,'KeyE')" @pointerup="emit('hold','KeyE',false)" @pointercancel="emit('hold','KeyE',false)" @lostpointercapture="emit('hold','KeyE',false)" @click="emit('nudge','KeyE')">E +</button></div><div class="keys"><button v-for="[key,label,action] in keys" :key="key" :aria-label="action" :disabled="paused" @pointerdown="down($event,key)" @pointerup="emit('hold',key,false)" @pointercancel="emit('hold',key,false)" @lostpointercapture="emit('hold',key,false)" @click="emit('nudge',key)"><kbd>{{ label }}</kbd><span>{{ action }}</span></button></div>
    <button class="legs" :disabled="paused||flight.legs||flight.phase!=='approach'" @click="emit('legs')">{{ flight.legs?'✓ Legs down':flight.phase==='approach'?'SPACE · Deploy legs':'Legs · below 800 m' }}</button>
    <div class="actions"><button :aria-pressed="flight.assist" :disabled="paused" @click="emit('assist')">{{ flight.assist?'Assist on':'Assist' }}</button><button :aria-label="paused?'Resume landing':'Pause landing'" @click="emit('pause')">{{ paused?'▶':'Ⅱ' }}</button><button aria-label="Retry landing" @click="emit('retry')">↺</button></div>
   </template>
   <template v-else><h3>{{ flight.status==='landed'?'Soft touchdown':'Try a gentler landing' }}</h3><p>{{ flight.result }}</p><button class="result" @click="flight.status==='landed'?emit('continue'):emit('retry')">{{ flight.status==='landed'?'Explore Mars':'Retry approach' }}</button></template>
  </div>
 </section>
</template>
<style scoped>
.landing-controls{position:absolute;inset:0;z-index:17;pointer-events:none;color:#ecf8f2}.descent-title{position:absolute;top:24px;left:50%;transform:translateX(-50%);display:grid;gap:7px;min-width:240px;text-align:center;padding:12px 16px;background:#102732df;border:1px solid #9fc9cc66;border-radius:12px;backdrop-filter:blur(12px)}small{font-size:9px;letter-spacing:.12em;color:#bad8d9}.descent-title strong{font-size:12px;color:#ffdf9e}.telemetry{position:absolute;left:24px;top:24px;padding:16px 18px;display:grid;gap:15px;min-width:120px;border:1px solid #9ac4c466;border-radius:12px;background:#102632e8}.telemetry small{display:block}.telemetry strong{font:22px/1.5 ui-monospace,monospace;font-variant-numeric:tabular-nums}.telemetry em{font:11px sans-serif;color:#bad4d8}.danger strong{color:#ffbe9b}.alignment{position:absolute;top:30%;left:50%;transform:translateX(-50%);width:240px;display:grid;gap:7px;text-align:center;font-size:9px;letter-spacing:.08em;text-shadow:0 1px 6px #000}.alignment span{color:#c0e9db}.alignment strong{font-weight:500;color:#e4f3ef}.lane{height:20px;border-bottom:1px solid #c3e0d288;position:relative}.pad{position:absolute;left:40%;right:40%;height:7px;bottom:-3px;background:#9eedc2;border-radius:3px}.lane b{position:absolute;top:0;color:#ffda91;transform:translateX(-50%);font-size:15px}.pilot-pad{position:absolute;right:24px;bottom:24px;width:260px;box-sizing:border-box;padding:14px;border:1px solid #92c4c766;border-radius:14px;background:#102b36ee;backdrop-filter:blur(12px);pointer-events:auto}.pilot-pad label{display:grid;grid-template-columns:1fr auto;gap:6px;color:#b6d7d4;font-size:10px;letter-spacing:.1em}.pilot-pad label strong{color:#ffe0a0}input{grid-column:1/-1;width:100%;min-height:30px;accent-color:#a0e9c7;margin:0}.keys{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:8px 0}.landing-controls button{min-height:40px;border:1px solid #8abcbf77;border-radius:8px;background:#254b58;color:#f1fff4;font-family:inherit;cursor:pointer}.keys button{display:flex;align-items:center;gap:8px;text-align:left;font-size:10px;touch-action:none;user-select:none;min-height:44px}.landing-controls button:active{background:#4b767b}kbd{padding:5px 7px;border-radius:5px;background:#112c3a;color:#ffdfa0;font:700 12px ui-monospace,monospace}.legs{width:100%;font-size:11px;background:#346158!important}.actions{display:flex;gap:8px;margin-top:9px}.actions button:first-child{margin-right:auto;min-width:75px;font-size:11px}.actions button{min-width:38px;font-size:16px}.actions button[aria-pressed=true]{border-color:#b7f5ca;background:#40776b}.landing-controls button:disabled{opacity:.45;cursor:default}.landing-controls button:focus-visible,input:focus-visible{outline:3px solid #ffdc97;outline-offset:3px}.pilot-pad h3{font-size:19px;color:#ffe0a0;margin:0 0 8px}.pilot-pad p{font-size:12px;line-height:1.5}.result{width:100%;background:#a0e5c8!important;color:#143a3c!important;font-weight:750}.heat{width:100%;height:4px;accent-color:#ffc38b;margin-top:2px}.thrust-keys{display:flex;align-items:center;justify-content:space-between;gap:5px;margin:5px 0}.thrust-keys button{min-width:42px;font-size:10px;touch-action:none}.thrust-keys span{font-size:7px;color:#b4d4cf;letter-spacing:.04em}.landing-controls *{box-sizing:border-box}@media(max-width:600px){.descent-title{top:65px;width:calc(100% - 24px);padding:9px;min-width:0}.telemetry{top:149px;left:12px;right:12px;display:flex;justify-content:space-between;gap:8px;padding:9px 12px;min-width:0}.telemetry strong{font-size:16px}.alignment{top:31%;width:200px;font-size:8px}.pilot-pad{right:12px;left:12px;bottom:12px;width:auto;padding:10px}.keys{grid-template-columns:repeat(4,1fr);gap:5px;margin:3px 0 7px}.keys button{display:grid;justify-items:center;gap:3px;font-size:8px;padding:6px 2px}.keys kbd{font-size:11px;padding:3px 7px}.legs{min-height:36px!important}.actions{margin-top:6px}.actions button{min-height:36px}.pilot-pad label{gap:0}}
</style>
